@implements IDisposable
@inject IJSRuntime JS

<div @ref="_container">
    @ChildContent
</div>

@code {
    [Parameter] public RenderFragment? ChildContent { get; set; }
    [Parameter] public int TimeoutSeconds { get; set; } = 300;
    [Parameter] public EventCallback OnIdle { get; set; }
    [Parameter] public EventCallback OnActive { get; set; }

    private ElementReference _container;
    private IJSObjectReference? _module;
    private DotNetObjectReference<UserActivityTracker>? _dotNetRef;

    private bool _isIdle;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            _dotNetRef = DotNetObjectReference.Create(this);
            _module = await JS.InvokeAsync<IJSObjectReference>(
                "import", "./Components/UserActivityTracker.razor.js");
            await _module.InvokeVoidAsync("initialize", _container, _dotNetRef, TimeoutSeconds * 1000);
        }
    }

    [JSInvokable]
    public async Task OnUserIdle()
    {
        if (!_isIdle)
        {
            _isIdle = true;
            await OnIdle.InvokeAsync();
        }
    }

    [JSInvokable]
    public async Task OnUserActive()
    {
        if (_isIdle)
        {
            _isIdle = false;
            await OnActive.InvokeAsync();
        }
    }

    public void Dispose()
    {
        if (_module is not null)
        {
            _ = _module.InvokeVoidAsync("dispose");
            _ = _module.DisposeAsync();
        }
        _dotNetRef?.Dispose();
    }
}

let timer = null;
let dotNetHelper = null;
let timeoutMs = 300000;
let isIdle = false;
let container = null;

const activityEvents = ["mousemove", "keydown", "click", "scroll"];

function handleActivity() {
    if (timer !== null) {
        clearTimeout(timer);
    }

    if (isIdle) {
        isIdle = false;
        dotNetHelper.invokeMethodAsync("OnUserActive");
    }

    timer = setTimeout(() => {
        isIdle = true;
        dotNetHelper.invokeMethodAsync("OnUserIdle");
    }, timeoutMs);
}

export function initialize(element, helper, timeout) {
    container = element;
    dotNetHelper = helper;
    timeoutMs = timeout;
    isIdle = false;

    for (const event of activityEvents) {
        container.addEventListener(event, handleActivity, { passive: true });
    }

    // Start the initial idle timer
    timer = setTimeout(() => {
        isIdle = true;
        dotNetHelper.invokeMethodAsync("OnUserIdle");
    }, timeoutMs);
}

export function dispose() {
    if (timer !== null) {
        clearTimeout(timer);
        timer = null;
    }

    if (container) {
        for (const event of activityEvents) {
            container.removeEventListener(event, handleActivity);
        }
        container = null;
    }

    dotNetHelper = null;
    isIdle = false;
}

